const separateParenGroups = (paren_string) => {
  const result = [];
  let currentGroup = '';
  let balance = 0;
  const cleaned = paren_string.replace(/\s+/g, '');

  for (let char of cleaned) {
    currentGroup += char;
    if (char === '(') {
      balance++;
    } else if (char === ')') {
      balance--;
    }

    if (balance === 0 && currentGroup.length > 0) {
      result.push(currentGroup);
      currentGroup = '';
    }
  }

  return result;
};

